function saveDemo(){if(isDemo)try{localStorage.setItem(demoStorageKey,JSON.stringify(db))}catch(e){console.warn('Demo browser storage unavailable',e)}}
function demoInit(){isDemo=true;let fresh=false;try{db=JSON.parse(localStorage.getItem(demoStorageKey)||'null')||seed();fresh=!localStorage.getItem(demoStorageKey)}catch{db=seed();fresh=true}const sample=fresh?db:seed();for(const collection of ['history','surveys','subsidies','loans','inventory','stockMovements','amcs','serviceTickets']){db[collection]=db[collection]||[];if(!db[collection].length&&sample[collection]?.length)db[collection]=sample[collection]}db.leads=db.leads.map(lead=>({...lead,stage:normalizeLeadStage(lead.stage)}));for(const project of db.installations){if(project.status==='Planning')project.status='Material Procurement';else if(project.status==='Material Ordered')project.status='Structure Installation';else if(project.status==='Structure')project.status='Module Installation';else if(project.status==='Panels')project.status='Inverter & Wiring';else if(project.status==='Wiring')project.status='Testing & Commissioning';else if(project.status==='Testing')project.status='DISCOM Inspection';else if(project.status==='Commissioned')project.status='Subsidy Disbursement'}if(!db.users.some(u=>u.role==='project_manager'))db.users.push({id:'demo-project-manager',name:'Project Manager',email:'project.manager@example.com',role:'project_manager',active:true});if(!db.users.some(u=>u.role==='project_executive'))db.users.push(...['Gokul T (Project)','Lakshmi K (Project)','Harish V (Project)'].map((name,i)=>({id:'demo-project-'+(i+1),name,email:'project'+(i+1)+'@example.com',role:'project_executive',active:true})));let last=null;try{last=localStorage.getItem(demoUserStorageKey)}catch{};currentUser=db.users.find(u=>u.id===last)||db.users[0];saveDemo();showApp()}
function loginError(e){let msg=e?.message||'Unable to sign in.';if(msg.includes('auth/invalid-credential')||msg.includes('auth/wrong-password'))msg='Incorrect email or password.';if(msg.includes('auth/operation-not-allowed'))msg='Google sign-in is not enabled for this Firebase project. Ask the administrator to enable the Google provider.';if(msg.includes('auth/unauthorized-domain'))msg='This website domain is not authorized for Firebase sign-in. Ask the administrator to add it in Firebase Authentication settings.';if(msg.includes('auth/popup-blocked'))msg='The Google sign-in popup was blocked. Allow popups for this site and try again.';if(msg.includes('Missing or insufficient permissions'))msg='You do not have permission for this workspace. Check the user profile and Firestore rules.';$('#login-error').textContent=msg;toast(msg,true)}
async function initFirebase(){
 isDemo=false;$('#login').classList.remove('hidden');const v='13.1.0';const [app,auth,store]=await Promise.all([import(`https://www.gstatic.com/firebasejs/${v}/firebase-app.js`),import(`https://www.gstatic.com/firebasejs/${v}/firebase-auth.js`),import(`https://www.gstatic.com/firebasejs/${v}/firebase-firestore.js`)]);
 const a=app.initializeApp(window.SOLARCRM_FIREBASE_CONFIG);fb={auth:auth.getAuth(a),store:store.getFirestore(a),authApi:auth,api:store};
 auth.onAuthStateChanged(fb.auth,async u=>{if(!u){currentUser=null;$('#app').classList.add('hidden');$('#login').classList.remove('hidden');return}try{
   const snap=await store.getDoc(store.doc(fb.store,'users',u.uid));if(!snap.exists()||snap.data().active!==true){await auth.signOut(fb.auth);toast('Account has no active CRM profile. Ask the administrator to add your UID to users.',true);return}
   currentUser={id:u.uid,uid:u.uid,...snap.data()};await fetchRecords();showApp();
 }catch(e){$('#app').classList.add('hidden');$('#login').classList.remove('hidden');loginError(e);if(e?.code==='permission-denied'||e?.message?.includes('Missing or insufficient permissions'))await auth.signOut(fb.auth)}});
 $('#login-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);$('#login-error').textContent='';try{await auth.signInWithEmailAndPassword(fb.auth,String(f.get('email')),String(f.get('password')))}catch(err){$('#login-error').textContent='Sign-in failed. Check your credentials.';loginError(err)}});
 $('#google-login').classList.remove('hidden');
 $('#google-login').addEventListener('click',async()=>{const provider=new auth.GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});$('#login-error').textContent='';try{await auth.signInWithPopup(fb.auth,provider)}catch(err){$('#login-error').textContent='Google sign-in failed.';loginError(err)}});
}
async function fetchRecords(){if(isDemo)return; const {collection,query,where,limit,getDocs}=fb.api;const assigned=!elevated();
 const cols=['leads','followups','quotations','installations','payments','history','surveys','subsidies','loans','inventory','stockMovements','amcs','serviceTickets'];let datasets=await Promise.all(cols.map(async c=>{
   let q=assigned&&c!=='inventory'?query(collection(fb.store,c),where('assignedTo','==',uid()),limit(1000)):query(collection(fb.store,c),limit(1000));let r=await getDocs(q);return r.docs.map(s=>({id:s.id,...s.data()}));
 }));cols.forEach((c,i)=>db[c]=datasets[i]);db.leads=db.leads.map(lead=>({...lead,stage:normalizeLeadStage(lead.stage)}));if(businessManager()){let r=await getDocs(query(collection(fb.store,'users'),limit(300)));db.users=r.docs.map(s=>({id:s.id,...s.data()}))}else if(salesManager()){const r=await getDocs(query(collection(fb.store,'users'),where('role','==','sales'),limit(300)));db.users=[{...currentUser},...r.docs.map(s=>({id:s.id,...s.data()}))]}else if(projectManager()){const r=await getDocs(query(collection(fb.store,'users'),where('role','in',['sales','manager','project_executive']),limit(300)));db.users=[{...currentUser},...r.docs.map(s=>({id:s.id,...s.data()}))]}else db.users=[{...currentUser}];
}
async function createHistory(entry){const item={...entry,actorId:uid(),actorName:currentUser.name||'Team member',createdAt:stamp()};if(isDemo){item.id='H-'+Date.now().toString(36)+Math.floor(Math.random()*999);db.history.unshift(item);saveDemo();return item.id}const r=await fb.api.addDoc(fb.api.collection(fb.store,'history'),item);return r.id}
function historyValue(field,value){if(value===undefined||value===null||value==='')return '(empty)';if(field==='assignedTo')return personOf(value);if(field==='leadId')return leadOf(value)?.customerName||String(value);if(field==='milestones'&&Array.isArray(value))return value.map(item=>`${item.name}: ${item.status}`).join('; ');if(typeof value==='boolean')return value?'Yes':'No';return String(value)}
async function writeRecord(col,item,id){const recordType=HISTORY_TYPES[col],tracksHistory=Boolean(recordType),previous=tracksHistory?db[col].find(r=>r.id===id):null;let recordId=id;
 if(isDemo){if(id){let i=db[col].findIndex(r=>r.id===id);if(i>=0)db[col][i]={...db[col][i],...item};else throw Error('Record not found')}else{item.id=col.slice(0,1).toUpperCase()+'-'+Date.now().toString(36)+Math.floor(Math.random()*999);db[col].unshift(item);recordId=item.id}saveDemo()}
 else if(id)await fb.api.updateDoc(fb.api.doc(fb.store,col,id),item);else{const r=await fb.api.addDoc(fb.api.collection(fb.store,col),item);recordId=r.id}
 if(tracksHistory){
  const recordIdForHistory=recordId||id,assignedTo=item.assignedTo||previous?.assignedTo;
  const base={recordType,recordId:recordIdForHistory,leadId:col==='leads'?recordIdForHistory:item.leadId||previous?.leadId,assignedTo,comment:''};
  if(!previous)await createHistory({...base,event:'Record created'});
  for(const [field,value] of Object.entries(item)){
  if(['id','createdAt','updatedAt','createdBy'].includes(field))continue;
   if(previous&&Object.is(previous[field],value))continue;
   const label=HISTORY_FIELD_LABELS[field]||field.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/^./,c=>c.toUpperCase());
   await createHistory({...base,event:previous?'Field changed':'Field set',field,fieldLabel:label,previousValue:historyValue(field,previous?.[field]),newValue:historyValue(field,value)});
  }
 }
 return recordId;
}
