function featureFieldMarkup(field,record){
 const value=record[field.name]??field.default??'';
 if(field.type==='select')return select(field.name,field.label,field.options,value||field.default||field.options[0],field.required!==false);
 if(field.type==='textarea')return textarea(field.name,field.label,Array.isArray(value)?value.join('\n'):value);
 return input(field.name,field.label,value,field.type||'text',field.required===true,field.extra||'');
}
