  {type:'installation',label:'Installation',page:'installations',collection:'installations',rows:visible(db.installations),title:r=>leadOf(r.leadId)?.customerName||'Installation',detail:r=>`${r.status} · ${r.installer||'No installer'} · ${dateLabel(r.targetDate)}`,text:r=>[r.id,leadOf(r.leadId)?.customerName,leadOf(r.leadId)?.city,r.status,r.installer,r.notes,r.targetDate,r.capacityKw].join(' ')},
  {type:'collection',label:'Collection',page:'payments',collection:'payments',rows:visible(db.payments),title:r=>leadOf(r.leadId)?.customerName||'Collection',detail:r=>`${r.kind} · ${r.status} · ${money(r.amount)}`,text:r=>[r.id,leadOf(r.leadId)?.customerName,r.kind,r.status,r.amount,r.dueDate].join(' ')}
  ,{type:'survey',label:'Site survey',page:'surveys',collection:'surveys',rows:visible(db.surveys),title:r=>leadOf(r.leadId)?.customerName||'Site survey',detail:r=>`${r.status} · ${dateLabel(r.surveyDate)}`,text:r=>[r.id,leadOf(r.leadId)?.customerName,r.discom,r.status,r.notes].join(' ')}
  ,{type:'subsidy',label:'Subsidy',page:'subsidies',collection:'subsidies',rows:visible(db.subsidies),title:r=>leadOf(r.leadId)?.customerName||'Subsidy application',detail:r=>`${r.status} · ${r.applicationNo||'No application number'}`,text:r=>[r.id,leadOf(r.leadId)?.customerName,r.applicationNo,r.status,r.notes].join(' ')}
  ,{type:'loan',label:'Loan',page:'loans',collection:'loans',rows:visible(db.loans),title:r=>leadOf(r.leadId)?.customerName||'Solar loan',detail:r=>`${r.bank||'Lender'} · ${r.status}`,text:r=>[r.id,leadOf(r.leadId)?.customerName,r.bank,r.applicationNo,r.status].join(' ')}
  ,{type:'serviceTicket',label:'Service ticket',page:'afterSales',collection:'serviceTickets',rows:visible(db.serviceTickets),title:r=>leadOf(r.leadId)?.customerName||'Service ticket',detail:r=>`${r.ticketType} · ${r.status}`,text:r=>[r.id,r.ticketNo,leadOf(r.leadId)?.customerName,r.ticketType,r.status,r.notes].join(' ')}
