  const taxableValue=lineItems.reduce((sum,item)=>sum+num(item.quantity)*num(item.unitPrice),0),gstAmount=lineItems.reduce((sum,item)=>sum+num(item.quantity)*num(item.unitPrice)*num(item.gstRate)/100,0),centralSubsidy=num(x.centralSubsidy),stateSubsidy=num(x.stateSubsidy),price=taxableValue+gstAmount;
  const data={leadId,assignedTo:l.assignedTo,lineItems,productId:lineItems[0].productId,productName:lineItems.length===1?lineItems[0].productName:`${lineItems.length} catalog items`,quantity:lineItems.reduce((sum,item)=>sum+num(item.quantity),0),unitPrice:lineItems[0].unitPrice,taxableValue,gstRate:taxableValue?gstAmount/taxableValue*100:0,gstAmount,cgstAmount:gstAmount/2,sgstAmount:gstAmount/2,centralSubsidy,stateSubsidy,customerPayable:Math.max(0,price-centralSubsidy-stateSubsidy),systemType:x.systemType,capacityKw:num(x.capacityKw),price,status:x.status,validUntil:x.validUntil,notes:x.notes,updatedAt:stamp()};
