 const legacyStage={'Planning':0,'Material Ordered':0,'Structure':1,'Panels':2,'Wiring':3,'Testing':4,'Commissioned':8,'Handover':10},legacyIndex=legacyStage[p.status]??INSTALLSTATUS.indexOf(p.status);
