 const lead=leadOf(payment.leadId),taxable=num(payment.amount),gst=num(payment.gstAmount??taxable*num(payment.gstRate)/100),content=`<h1>GST Invoice</h1><p><strong>${esc(window.SOLARCRM_COMPANY_NAME||'Solar Company Name')}</strong><br>GSTIN: ${esc(payment.gstin||'Not configured')}</p><p>Invoice: ${esc(payment.invoiceNo||payment.id)} · Date: ${dateLabel(payment.dueDate)}</p><p><strong>Bill to:</strong> ${esc(lead?.customerName||'Customer')}<br>${esc(lead?.city||'')} · ${esc(lead?.phone||'')}</p><table><thead><tr><th>Description</th><th>Taxable value</th><th>CGST</th><th>SGST</th><th>Total</th></tr></thead><tbody><tr><td>${esc(payment.kind)} for solar project</td><td>${money(taxable)}</td><td>${money(gst/2)}</td><td>${money(gst/2)}</td><td>${money(taxable+gst)}</td></tr></tbody></table><p class="total">Invoice total: ${money(taxable+gst)}</p>`;
 openPrintWindow(`Invoice ${payment.invoiceNo||payment.id}`,content)
