function exportReport(){
 const sources=new Map();for(const lead of visible(db.leads)){const key=lead.source||'Other',item=sources.get(key)||{leads:0,won:0};item.leads++;if(lead.stage==='Won')item.won++;sources.set(key,item)}
 const csv=[['Source','Leads','Won','Conversion'],...sources.entries().map(([source,item])=>[source,item.leads,item.won,`${item.leads?Math.round(item.won/item.leads*100):0}%`]),['',''],['Pipeline stage','Leads','Quoted value'],...STAGES.map(stage=>{const leads=visible(db.leads).filter(l=>l.stage===stage);return [stage,leads.length,leads.reduce((sum,l)=>sum+amountOf(l),0)]})].map(row=>row.map(value=>'"'+String(value??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');
 const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'})),link=document.createElement('a');link.href=url;link.download=`MySolarDesk_Sales_Report_${today()}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),500)
}
